'use client'; import { useState } from 'react'; import { API, Order } from '@/lib/api';
const statuses=['PENDING','CONFIRMED','PACKED','SHIPPED','DELIVERED','CANCELLED'];
export default function OrderManager({initial}:{initial:Order[]}){const [orders,setOrders]=useState(initial);const update=async(id:string,status:string)=>{const r=await fetch(`${API}/orders/${id}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});if(r.ok)setOrders(x=>x.map(o=>o.id===id?{...o,status}:o));};return <div className="card overflow-x-auto"><table className="w-full min-w-[980px] text-left text-sm"><thead><tr className="bg-[#fafaf8] text-[10px] font-bold uppercase text-muted"><th className="px-5 py-4">Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Payment</th><th>Status</th><th>Placed</th></tr></thead><tbody>{orders.map(o=><tr className="border-t border-line" key={o.id}><td className="px-5 py-4 font-bold">{o.orderNumber}</td><td><p className="font-bold">{o.customerName}</p><p className="text-xs text-muted">{o.phone} · {o.city}</p></td><td>{o.items?.reduce((a,i)=>a+i.quantity,0)||0} pieces</td><td className="font-bold">৳{o.total.toLocaleString()}</td><td><span className={`rounded-full px-2 py-1 text-[10px] font-bold ${o.paymentMethod==='BKASH'?'bg-pink-100 text-pink-700':o.paymentMethod==='NAGAD'?'bg-orange-100 text-orange-700':'bg-neutral-100'}`}>{o.paymentMethod||'COD'}</span>{o.transactionId&&<p className="mt-1 text-[10px] text-muted">Trx: {o.transactionId}<br/>{o.paymentNumber}</p>}</td><td><select value={o.status} onChange={e=>update(o.id,e.target.value)} className="rounded-lg border border-line bg-white px-3 py-2 text-xs font-bold">{statuses.map(s=><option key={s}>{s}</option>)}</select></td><td>{new Date(o.createdAt).toLocaleDateString()}</td></tr>)}</tbody></table></div>}
